import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

/**
 * Local development authentication endpoint
 * This creates a test session for local development only
 * DO NOT use in production - only works when NODE_ENV is 'development'
 */
export async function GET(request: Request) {
  // Only allow in development
  if (process.env.NODE_ENV !== 'development') {
    return NextResponse.json({ error: 'Not available in production' }, { status: 403 });
  }

  try {
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
    const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

    if (!supabaseUrl || !serviceRoleKey) {
      return NextResponse.json({ error: 'Missing Supabase configuration' }, { status: 500 });
    }

    // Get the return URL
    const url = new URL(request.url);
    const returnTo = url.searchParams.get('returnTo') || '/scheduling';

    // Create admin client
    const supabaseAdmin = createClient(supabaseUrl, serviceRoleKey, {
      auth: {
        autoRefreshToken: false,
        persistSession: false
      }
    });

    const testEmail = 'dev@localhost.test';
    const testOrgId = 'dev-local-test';

    // Find or create company
    let { data: company } = await supabaseAdmin
      .from('companies')
      .select('id')
      .eq('whop_org_id', testOrgId)
      .maybeSingle();

    if (!company) {
      const { data: newCompany, error: companyError } = await supabaseAdmin
        .from('companies')
        .insert({
          whop_org_id: testOrgId,
          slug: `dev-local-${Date.now()}`,
          name: 'Local Dev Company',
          plan_id: 'preview',
          booking_slug_prefix: `dev${Date.now()}`.slice(0, 32),
          primary_contact_email: testEmail,
        })
        .select('id')
        .single();

      if (companyError) {
        console.error('Company creation error:', companyError);
        return NextResponse.json({ error: 'Failed to create company', details: companyError.message }, { status: 500 });
      }
      company = newCompany;
    }

    // Find or create user
    let { data: { users } } = await supabaseAdmin.auth.admin.listUsers();
    let user = users.find(u => u.email === testEmail);

    if (!user) {
      const { data: newUser, error: userError } = await supabaseAdmin.auth.admin.createUser({
        email: testEmail,
        email_confirm: true,
        user_metadata: {
          company_id: company.id,
          company_name: 'Local Dev Company',
          whop_org_id: testOrgId,
          name: 'Local Dev User',
        }
      });

      if (userError) {
        console.error('User creation error:', userError);
        return NextResponse.json({ error: 'Failed to create user', details: userError.message }, { status: 500 });
      }
      user = newUser.user;
    }

    // Create company member if needed
    const { error: memberError } = await supabaseAdmin
      .from('company_members')
      .upsert(
        { company_id: company.id, user_id: user.id, role: 'owner' },
        { onConflict: 'company_id,user_id' }
      );

    if (memberError) {
      console.error('Member upsert error:', memberError);
    }

    // Set a known password for the dev user
    const devPassword = 'dev-local-password-12345';

    // Update user's password
    const { error: passwordError } = await supabaseAdmin.auth.admin.updateUserById(
      user.id,
      { password: devPassword }
    );

    if (passwordError) {
      console.error('Password update error:', passwordError);
      return NextResponse.json({ error: 'Failed to set password', details: passwordError.message }, { status: 500 });
    }

    // Redirect to client-side login page that will sign in with password
    const loginUrl = `${url.origin}/api/dev-auth/login?email=${encodeURIComponent(testEmail)}&password=${encodeURIComponent(devPassword)}&returnTo=${encodeURIComponent(returnTo)}`;
    return NextResponse.redirect(loginUrl);
  } catch (error) {
    console.error('Dev auth error:', error);
    return NextResponse.json({
      error: 'Failed to authenticate',
      details: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 });
  }
}
